window.HOEREN_TESTS[40] = {"id":"winter-und-skifahren","name":"Winter und Skifahren","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Wintersportler, eine Information vom Ski-Resort Alpenhof: Heute sind die Pisten geschlossen. Es schneit zu stark, Sichtweite unter 10 Metern. Gefährlich! Morgen sind wir wieder offen. Lift-Tickets bleiben gültig. Wir entschuldigen uns für die Unannehmlichkeiten. Vielen Dank für Ihr Verständnis. Bitte bleiben Sie im Hotel und warten Sie auf morgen.","gender":"f","q":"Warum sind die Pisten geschlossen?","opts":["Technische Probleme.","Schlechtes Wetter.","Mitarbeiter-Streik."],"correct":1},{"transcript":"Hallo Markus, hier ist Tom. Ich habe meine Skier vergessen — kannst du mir deine leihen? Im Geschäft kosten sie 30 Euro pro Tag, für eine Woche viel zu teuer. Deine alten Skier passen mir vielleicht. Einen Schlitten habe ich schon, aber damit fahre ich nicht gern. Bring die Skier morgen mit, wenn du kommst, okay? Danke!","gender":"m","q":"Was möchte Tom?","opts":["Skier kaufen.","Schlitten leihen.","Skier leihen von Markus."],"correct":2},{"transcript":"Achtung Skifahrer: Auf der schwarzen Piste 7 gibt es eisige Stellen heute Morgen. Vorsicht beim Fahren! Wir empfehlen erfahrenen Skifahrern blaue oder rote Pisten heute. Wer trotzdem schwarz fahren möchte, bitte vorsichtig und langsam. Helm ist Pflicht. Mehr Infos beim Lift-Personal. Fahren Sie bitte nur mit Helm und langsam.","gender":"m","q":"Was wird empfohlen?","opts":["Blaue oder rote Pisten.","Nur schwarze Pisten.","Nicht Ski fahren."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, ich habe mir das Bein gebrochen beim Skifahren! Bin im Krankenhaus, Gipsbein für 6 Wochen. Zum Glück nur das Bein, nicht der Arm, und keine Erkältung dazu. Der Skiurlaub ist zu Ende. Komm mich bitte besuchen, Besuch wäre schön. Markus ist auch hier. Krankenhaus Innsbruck, Zimmer 304.","gender":"f","q":"Was ist passiert?","opts":["Anna hat sich den Arm gebrochen.","Anna hat eine Erkältung.","Anna hat sich das Bein gebrochen."],"correct":2},{"transcript":"Liebe Gäste des Hotel Bergblick: Die Skischule bietet jetzt neue Kurse an. Anfänger-Kurs morgen 9 Uhr, Mittelstufe 11 Uhr, Fortgeschrittene 14 Uhr. Der Kurs um 9 Uhr ist fast voll, also bitte schnell anmelden. Treffpunkt unten am Lift. Anmeldung an der Hotelrezeption. Preis 50 Euro pro Tag inklusive Mittagessen. Wir freuen uns!","gender":"f","q":"Wann ist der Anfänger-Kurs?","opts":["11 Uhr.","9 Uhr.","14 Uhr."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Schnee auf dem Berg ist endlich tief genug."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Der Kalender ist noch frei. Wir können fünf Tage füllen."},{"speaker":"Lukas","gender":"m","text":"Snowboarden steht montags an. Die steile Piste ist dann frei."},{"speaker":"Lisa","gender":"f","text":"Du bist mutiger als ich. Ich bleibe auf der normalen Spur."},{"speaker":"Lukas","gender":"m","text":"Sollen wir auch Curling ausprobieren?"},{"speaker":"Lisa","gender":"f","text":"Nein. Wir machen kein Curling."},{"speaker":"Lukas","gender":"m","text":"Einen Tag später triffst du den Lehrer an der Talstation."},{"speaker":"Lisa","gender":"f","text":"Ich fahre am Dienstag Ski. Das übe ich seit dem letzten Winter."},{"speaker":"Lukas","gender":"m","text":"In der Stadt haben wir am Mittwoch noch Platz für alle."},{"speaker":"Lisa","gender":"f","text":"Wir gehen Schlittschuhlaufen. Die Schuhe liegen unten im Flur."},{"speaker":"Lukas","gender":"m","text":"Die Kleinen kommen am Donnerstag mit auf den Hügel."},{"speaker":"Lisa","gender":"f","text":"Schlitten fahren ist dann dran. Der Hang hinter dem Haus ist sanft."},{"speaker":"Lukas","gender":"m","text":"Wollen wir auch Skispringen versuchen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Skispringen versuchen wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Die Jungs wollen am Freitag etwas Schnelles auf dem Eis."},{"speaker":"Lisa","gender":"f","text":"Sie spielen Eishockey. Die Schläger liegen schon im Auto."},{"speaker":"Lukas","gender":"m","text":"Ich hänge den Plan neben die Wohnungstür."},{"speaker":"Lisa","gender":"f","text":"Morgens ziehen wir dann die passenden Sachen an."}],"options":[{"letter":"a","text":"Curling"},{"letter":"b","text":"Schlittschuhlaufen"},{"letter":"c","text":"Skispringen"},{"letter":"d","text":"Ski fahren"},{"letter":"e","text":"Snowboarden"},{"letter":"f","text":"Eishockey"},{"letter":"g","text":"Schlitten fahren"},{"letter":"h","text":"Langlauf"},{"letter":"i","text":"Eisklettern"}],"items":[{"person":"Montag","correct":"e"},{"person":"Dienstag","correct":"d"},{"person":"Mittwoch","correct":"b"},{"person":"Donnerstag","correct":"g"},{"person":"Freitag","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Was kostet ein Lift-Ticket für einen Tag? Wir sind eine Familie mit zwei Kindern."},{"speaker":"Verkäuferin","gender":"f","text":"Erwachsene zahlen 45 Euro, Kinder bis 14 Jahre 25 Euro. Zusammen wären das 140 Euro."},{"speaker":"Kunde","gender":"m","text":"140 Euro ist viel. Gibt es eine Familienkarte, vielleicht für 100 Euro?"},{"speaker":"Verkäuferin","gender":"f","text":"Für 100 Euro leider nicht, aber die Familienkarte kostet 120 Euro statt 140. Sie sparen 20 Euro."},{"speaker":"Kunde","gender":"m","text":"Gut, dann nehmen wir die Familienkarte für 120 Euro. Danke!"}],"q":"Was kostet die Familienkarte?","opts":["140 Euro.","120 Euro.","100 Euro."],"correct":1},{"lines":[{"speaker":"Skifahrerin","gender":"f","text":"Guten Tag! Können Sie meine Skier reparieren? Die Bindung ist locker."},{"speaker":"Techniker","gender":"m","text":"Kein Problem, das geht schnell. In 15 Minuten schaffe ich es nicht, aber in 30 Minuten ja."},{"speaker":"Skifahrerin","gender":"f","text":"30 Minuten ist okay. Und was kostet das?"},{"speaker":"Techniker","gender":"m","text":"25 Euro. Eine Stunde dauert es sicher nicht, keine Sorge."},{"speaker":"Skifahrerin","gender":"f","text":"Gut, dann warte ich hier im Café. Bis gleich!"}],"q":"Wie lange dauert die Reparatur?","opts":["30 Minuten.","15 Minuten.","Eine Stunde."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Tim, es ist minus 10 Grad! Ziehst du die Mütze und den Schal an?"},{"speaker":"Tim","gender":"m","text":"Mama, mir ist nicht kalt. Der Schal kratzt so."},{"speaker":"Mutter","gender":"f","text":"Bitte beides, sonst wirst du krank!"},{"speaker":"Tim","gender":"m","text":"Okay, die Mütze ja, aber den Schal lasse ich hier."},{"speaker":"Mutter","gender":"f","text":"Na gut, aber die Mütze bleibt auf dem Kopf, versprochen?"},{"speaker":"Tim","gender":"m","text":"Versprochen! Tschüss, Mama!"}],"q":"Was zieht Tim an?","opts":["Nur Mütze.","Nur Schal.","Beides."],"correct":0},{"lines":[{"speaker":"Skifahrer1","gender":"m","text":"Guten Morgen! Welche Piste fahren wir zuerst?"},{"speaker":"Skifahrer2","gender":"m","text":"Schwarz ist mir zu schwer heute, da habe ich Angst."},{"speaker":"Skifahrer1","gender":"m","text":"Gut, dann rot? Die rote Piste ist schön lang."},{"speaker":"Skifahrer2","gender":"m","text":"Rot ist okay, aber zum Warmwerden fahren wir erst blau, einverstanden?"},{"speaker":"Skifahrer1","gender":"m","text":"Einverstanden! Erst blau, dann rot. Viel Spaß!"},{"speaker":"Skifahrer2","gender":"m","text":"Einverstanden! Bis später am Lift, viel Spaß!"}],"q":"Welche Piste zuerst?","opts":["Schwarz.","Rot.","Blau."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Sara, möchtest du in die Skischule oder lieber mit uns Eltern fahren?"},{"speaker":"Sara","gender":"f","text":"In die Skischule! Da sind andere Kinder, das macht mehr Spaß."},{"speaker":"Vater","gender":"m","text":"Sicher? Wir zeigen dir auch gerne alles. Oder möchtest du Schlitten fahren?"},{"speaker":"Sara","gender":"f","text":"Nein, kein Schlitten. Ich will Ski lernen, mit Kindern zusammen."},{"speaker":"Vater","gender":"m","text":"Gut, dann melde ich dich an. Viel Spaß in der Skischule!"}],"q":"Was möchte Sara?","opts":["Mit Eltern fahren.","In die Skischule.","Schlitten fahren."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Berger, einem Skilehrer. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Berger, Sie arbeiten als Skilehrer in den österreichischen Alpen seit 20 Jahren. Wie sind Sie dazu gekommen?"},{"speaker":"Berger","gender":"m","text":"Ich komme aus Tirol, bin praktisch auf Skiern aufgewachsen. Schon mit drei Jahren bin ich gefahren. Mit 18 die Ausbildung gemacht, seitdem Skilehrer. Im Sommer arbeite ich als Wanderführer in den gleichen Bergen."},{"speaker":"Reporterin","gender":"f","text":"Welche Schüler kommen zu Ihnen?"},{"speaker":"Berger","gender":"m","text":"Alle Niveaus, aber meistens Anfänger. Touristen, die noch nie auf Skiern waren — sehr gemischt. Kinder, Erwachsene, Senioren. Ich unterrichte am liebsten Kinder, die lernen am schnellsten."},{"speaker":"Reporterin","gender":"f","text":"Was ist der häufigste Fehler von Anfängern?"},{"speaker":"Berger","gender":"m","text":"Sie haben Angst und lehnen nach hinten. Aber beim Skifahren muss man nach vorne lehnen — gegen den Berg, nicht gegen die Schwerkraft. Das umzulernen dauert oft Tage. Ohne Vertrauen geht nichts."},{"speaker":"Reporterin","gender":"f","text":"Gibt es viele Verletzungen?"},{"speaker":"Berger","gender":"m","text":"Leider ja, knieverletzungen am häufigsten. Auch Daumen — beim Fallen drückt der Skistock falsch. Helmpflicht hat geholfen — Kopfverletzungen sind weniger geworden. Aber Knie bleibt problematisch."},{"speaker":"Reporterin","gender":"f","text":"Was sollten Skifahrer machen, um sicher zu sein?"},{"speaker":"Berger","gender":"m","text":"Vor der Saison Sport machen, Beine stärken! Helm tragen. Auf das eigene Niveau achten — nicht schwarze Piste, wenn man rot kaum schafft. Und Pausen machen, wenn müde — die meisten Unfälle passieren am Nachmittag."}],"items":[{"q":"Er unterrichtet am liebsten Erwachsene.","correct":"nein"},{"q":"Im Sommer arbeitet er als Wanderführer.","correct":"ja"},{"q":"Herr Berger ist in den Alpen aufgewachsen.","correct":"ja"},{"q":"Knieverletzungen sind die häufigsten beim Skifahren.","correct":"ja"},{"q":"Die meisten Unfälle passieren am Morgen.","correct":"nein"}]}]};
